-- One-off setup for the client New Book World (owner: Ashish, login viralwechaar@gmail.com): AUZsScan + their own invoice layout.
-- Apply by hand, once, AFTER db/149 and db/150:
--   set -a; source .env; set +a
--   docker compose exec -T postgres psql -U "$POSTGRES_USER" -d "$POSTGRES_DB" -v ON_ERROR_STOP=1 < db_data/new_book_world_setup.sql
-- (Logo: the client's own file.) Safe to run again (every step checks first). Needs the owner to have signed in to AUZslab once so the login exists.
-- Everything below comes from their own tax invoice (name, GSTIN, address, phone, email, bank, terms, logo).
begin;
do $$
declare uid uuid; tid uuid; org jsonb; brand jsonb; r jsonb;
begin
  select id into uid from auth_users where lower(email) = 'viralwechaar@gmail.com' and deleted_at is null;
  if uid is null then raise exception 'No login for viralwechaar@gmail.com yet: ask them to sign in once at auzslab.in (Google), then run this again'; end if;

  select tenant_id into tid from profiles where id = uid;
  if tid is null then
    select id into tid from tenants where slug = 'newbookworld';
    if tid is null then
      insert into tenants (name, slug, niche, status) values ('New Book World', 'newbookworld', 'retail', 'active') returning id into tid;
    end if;
    insert into records (id, tenant_id, kind, data) values ('settings', tid, 'settings', jsonb_build_object('name', 'New Book World')) on conflict do nothing;
    insert into profiles (id, tenant_id, email, role) values (uid, tid, 'viralwechaar@gmail.com', 'owner');
    update auth_users set app_metadata = coalesce(app_metadata, '{}'::jsonb) || jsonb_build_object('tenant_id', tid, 'role', 'owner') where id = uid;
    update signup_requests set status = 'approved' where user_id = uid and status = 'pending';
  end if;
  update tenants set name = 'New Book World', monthly_fee = 460 where id = tid;

  -- the product they bought: AUZsScan only
  insert into tenant_settings (tenant_id, features) values (tid, '{"scan": true}'::jsonb)
    on conflict (tenant_id) do update set features = coalesce(tenant_settings.features, '{}'::jsonb) || '{"scan": true}'::jsonb;

  -- act as the owner so the accounting functions see the right business and role
  perform set_config('app.uid', uid::text, true);
  perform acc_bootstrap();
  brand := jsonb_build_object(
    'invoiceStyle', 'classic',
    'logo', 'data:image/png;base64,',
    'bank', jsonb_build_object('holder', 'New Book World', 'name', 'STATE BANK OF INDIA', 'account', '00000042694307337', 'ifsc', 'SBIN0031201', 'branch', ''));
  r := acc_save_org(jsonb_build_object(
    'legal_name', 'New Book World', 'trade_name', 'New Book World',
    'gstin', '08AAVFN9235H1ZL', 'pan', 'AAVFN9235H', 'state_code', '08', 'reg_type', 'regular',
    'address', 'Near Shanichar Ji Ka Than', 'city', 'Jodhpur', 'phone', '8595977777', 'email', 'newbookworldjodhpur@gmail.com',
    'invoice_terms', E'E.& O.E.\n1. Goods once sold will not be taken back.\n2. Interest @ 18% p.a. will be charged if the payment is not made with in the stipulated time.\n3. Subject to ''Jodhpur'' Jurisdiction only.\n4.* preowned.',
    'settings', jsonb_build_object('brand', brand, 'number_style', 'plain')));

  -- the item on their sample bill (Patanjali notebook, MRP 60, sold at 45, GST exempt), so scanning works on day one
  if not exists (select 1 from acc_products where tenant_id = tid and sku = 'PAT-NB-172') then
    perform acc_save_product(jsonb_build_object('id', null, 'name', 'Patanjali Notebook 172pg 60/-', 'sku', 'PAT-NB-172', 'barcode', '', 'category', 'Notebooks', 'brand', 'Patanjali',
      'unit', 'Nos', 'hsn', '', 'tax_rate', '0', 'tax_inclusive', false, 'sale_price', '45', 'purchase_price', '0', 'mrp', 60, 'is_service', false, 'track_stock', true,
      'track_batch', false, 'track_serial', false, 'reorder_level', 0, 'reorder_qty', 0, 'notes', '', 'active', true, 'price_lists', '{}'::jsonb));
  end if;
  raise notice 'New Book World is set up (tenant %). Address: https://newbookworld.auzslab.in/scan.html', tid;
end $$;
commit;
